      sourceUrl: "https://api.fda.gov/drug/label.json?search=openfda.generic_name:%22Glipizide%22&limit=1",
      sourceHash: "41253acd76e6a96f3b274c365879563c501e01f31c608f1308b44ce3a7012f41",
      extractedAt: "2026-05-28T15:33:35.334Z",
      extractor: "openfda-labels@v1",
      confidence: 0.9,
