      sourceUrl: "https://api.fda.gov/drug/label.json?search=openfda.generic_name:%22Mesalamine%22&limit=1",
      sourceHash: "2957a1b1186a0195c27bd2ceb5237c34ab588e004044bc2ea49e7239ccd365b9",
      extractedAt: "2026-05-28T15:33:35.334Z",
