      sourceUrl: "https://api.fda.gov/drug/label.json?search=openfda.generic_name:%22Mycophenolate%22&limit=1",
      sourceHash: "a9ee79581836dd0ca576b6bc2163b55d798f2857a9e4c2dfc24c7f99a53931cd",
      extractedAt: "2026-05-28T18:21:00.826Z",
