      sourceUrl: "https://api.fda.gov/drug/label.json?search=openfda.generic_name:%22Pioglitazone%22&limit=1",
      sourceHash: "edada9359e999ece0140b98cea859bcb2d278f089a4464f52d2c8293f1c32e27",
      extractedAt: "2026-05-28T14:18:30.135Z",
      extractor: "openfda-labels@v1",
